-- More Bangladeshi foods (99: local + imported), food types with nutrients per 100 g from USDA FoodData Central
-- (SR Legacy 2018-04 / Foundation 2025-04, public domain; each type cites its FDC id), and typical fruit seasons in
-- Bangladesh. New foods carry NO condition verdicts until a reviewer adds them. Photos: Pexels License, each checked by eye.
CREATE TABLE food_variants (
  id         serial PRIMARY KEY,
  food_id    integer NOT NULL REFERENCES foods (id) ON DELETE CASCADE,
  slug       varchar(60) NOT NULL,
  name       jsonb NOT NULL,
  is_default boolean NOT NULL DEFAULT false,
  per_100g   jsonb NOT NULL DEFAULT '{}'::jsonb,
  source     varchar(40) NOT NULL,
  source_ref varchar(40),
  sort       integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (food_id, slug)
);
CREATE TRIGGER food_variants_updated_at BEFORE UPDATE ON food_variants FOR EACH ROW EXECUTE FUNCTION set_updated_at();
-- months 1-12 when the food is typically in season in the country pack (NULL = not seasonal / imported)
ALTER TABLE foods ADD COLUMN season jsonb;

